/**
 * Fetch WIP Storage Locations from the selected Work Order
 * and copy them to Stock Entry.custom_storage_location.
 */
async function fetch_wip_locations(frm) {
    if (!frm.doc.work_order || frm.doc.docstatus !== 0) {
        return;
    }

    const work_order_name = frm.doc.work_order;

    // Prevent duplicate requests for the same Work Order.
    if (frm.__fetching_wip_locations === work_order_name) {
        return;
    }

    frm.__fetching_wip_locations = work_order_name;

    try {
        const response = await frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Work Order",
                name: work_order_name
            }
        });

        // Ignore the response if the selected Work Order changed.
        if (frm.doc.work_order !== work_order_name) {
            return;
        }

        const work_order = response.message;

        if (!work_order) {
            frappe.msgprint(
                __("Could not load Work Order {0}.", [
                    work_order_name
                ])
            );
            return;
        }

        const wip_rows =
            work_order.custom_workinprogress_warehouse_storage_location || [];

        console.log("Selected Work Order:", work_order_name);
        console.log("Fetched WIP Storage Location rows:", wip_rows);

        if (!wip_rows.length) {
            frappe.msgprint(
                __("No WIP Storage Location rows found in Work Order {0}.", [
                    work_order_name
                ])
            );
            return;
        }

        // Check that the source rows contain Warehouse values.
        const missing_warehouse = wip_rows.filter(
            row => row.item && !row.warehouse
        );

        if (missing_warehouse.length) {
            frappe.msgprint({
                title: __("Missing Warehouse in Work Order"),
                indicator: "orange",
                message: __(
                    "Please populate Warehouse for these items in the Work Order: {0}",
                    [
                        missing_warehouse
                            .map(row => row.item)
                            .join(", ")
                    ]
                )
            });
        }

        // Clear the existing Storage Location rows.
        frm.clear_table("custom_storage_location");

        // Copy each Work Order row into Stock Entry.
        for (const source of wip_rows) {
            const target = frm.add_child("custom_storage_location");

            target.item = source.item || "";

            // Explicitly copy the Warehouse Link value.
            target.warehouse = source.warehouse || "";

            target.floor = source.floor || "";
            target.area = source.area || "";
            target.shelf = source.shelf || "";
            target.rack = source.rack || "";
            target.uom = source.uom || "";
            target.quantity = flt(source.quantity || 0);

            console.log("Copied Storage Location row:", {
                item: source.item,
                source_warehouse: source.warehouse,
                target_warehouse: target.warehouse,
                floor: target.floor
            });
        }

        // Refresh the child table display.
        frm.refresh_field("custom_storage_location");

        // Inspect actual document values immediately after copying.
        console.log("Stock Entry rows immediately after copying:");

        console.table(
            (frm.doc.custom_storage_location || []).map(row => ({
                item: row.item,
                warehouse: row.warehouse,
                floor: row.floor,
                area: row.area,
                shelf: row.shelf,
                rack: row.rack,
                uom: row.uom,
                quantity: row.quantity
            }))
        );

        // Notify if the copied values are still missing.
        const copied_missing_warehouse =
            (frm.doc.custom_storage_location || []).filter(
                row => row.item && !row.warehouse
            );

        if (copied_missing_warehouse.length) {
            frappe.msgprint({
                title: __("Warehouse Missing"),
                indicator: "red",
                message: __(
                    "Warehouse is missing for: {0}. Check the console and other Client Scripts.",
                    [
                        copied_missing_warehouse
                            .map(row => row.item)
                            .join(", ")
                    ]
                )
            });
        } else {
            frappe.show_alert({
                message: __("WIP Storage Locations copied successfully."),
                indicator: "green"
            });
        }

    } catch (error) {
        console.error(
            "WIP Storage Location fetch failed:",
            error
        );

        frappe.msgprint(
            __("Failed to fetch WIP Storage Locations. Check the browser console.")
        );

    } finally {
        if (frm.__fetching_wip_locations === work_order_name) {
            frm.__fetching_wip_locations = null;
        }
    }
}

