    settings.onload = function (listview) {
        if (old_onload) {
            old_onload.call(this, listview);
        }
        add_storage_button(listview);
    };

    settings.refresh = function (listview) {
        if (old_refresh) {
            old_refresh.call(this, listview);
        }
        add_storage_button(listview);
    };
})();

