// Stock Entry: cascading location filter for the Storage Location table
// Warehouse -> Floor -> Area -> Shelf -> Rack
(function () {

const SE_LOCATION_TABLE = "custom_storage_location";

frappe.ui.form.on("Stock Entry", {
    setup(frm) {
        frm.set_query("floor", SE_LOCATION_TABLE, se_location_query(["warehouse"]));
        frm.set_query("area", SE_LOCATION_TABLE, se_location_query(["warehouse", "floor"]));
        frm.set_query("shelf", SE_LOCATION_TABLE, se_location_query(["warehouse", "floor", "area"]));
        frm.set_query("rack", SE_LOCATION_TABLE, se_location_query(["warehouse", "floor", "area", "shelf"]));

        register_se_location_clear_events();
    }
});


// Builds the filter: every field in the list must already be chosen in the row,
// and the list shows only the records that belong to those values.
function se_location_query(required_fields) {
    return function (doc, cdt, cdn) {
        const row = locals[cdt][cdn];
        const filters = {};

        for (const fieldname of required_fields) {
            if (!row[fieldname]) {
                return {
                    filters: {
                        name: ["=", "__no_matching_location__"]
                    }
                };
            }

            filters[fieldname] = row[fieldname];
        }

        return { filters };
    };
}


// When a field changes, clear the fields below it.
function register_se_location_clear_events() {
    const df = frappe.meta.get_docfield("Stock Entry", SE_LOCATION_TABLE);

    if (!df) {
        return;
    }

    window.__se_location_clear_registered = window.__se_location_clear_registered || {};

    if (window.__se_location_clear_registered[df.options]) {
        return;
    }

    window.__se_location_clear_registered[df.options] = true;

    frappe.ui.form.on(df.options, {
        warehouse(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["floor", "area", "shelf", "rack"]);
        },

        floor(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["area", "shelf", "rack"]);
        },

        area(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["shelf", "rack"]);
        },

        shelf(frm, cdt, cdn) {
            clear_se_location_fields(frm, cdt, cdn, ["rack"]);
        }
    });
}


function clear_se_location_fields(frm, cdt, cdn, fields) {
    if (frm.doctype !== "Stock Entry") {
        return;
    }

    fields.forEach(fieldname => {
        const row = locals[cdt][cdn];

        if (row && row[fieldname]) {
            frappe.model.set_value(cdt, cdn, fieldname, "");
        }
    });
}

